const toggle=document.querySelector('.menu-toggle');const nav=document.querySelector('.site-nav');if(toggle&&nav){toggle.addEventListener('click',()=>{const open=nav.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open));});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>nav.classList.remove('open')))}document.querySelectorAll('#year').forEach(el=>el.textContent=new Date().getFullYear());const reveals=document.querySelectorAll('.reveal');if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.12});reveals.forEach(el=>observer.observe(el))}else{reveals.forEach(el=>el.classList.add('visible'))}const form=document.querySelector('#booking-form');if(form){form.addEventListener('submit',e=>{e.preventDefault();document.querySelector('#form-message').textContent='Demo request received. Connect this form to the client’s booking platform or email before launch.';form.reset()})}document.querySelectorAll('.add-cart').forEach(btn=>btn.addEventListener('click',()=>{document.querySelector('#cart-note').textContent=`${btn.dataset.product} added to the demo cart. Connect a payment provider to complete checkout.`}))